void visit(Node node, List<Node> order) {        // node, then its child level, then the rest
    for (Node curr = node; curr != null; curr = curr.next) {
        order.add(curr);
        if (curr.child != null) visit(curr.child, order);
    }
}

void visit(Node* node, vector<Node*>& order) {   // node, then its child level, then the rest
    for (Node* curr = node; curr != nullptr; curr = curr->next) {
        order.push_back(curr);
        if (curr->child != nullptr) visit(curr->child, order);
    }
}

