function flatten(head) {
  if (head === null) return null;
  const stack = [head];
  let prev = null;
  while (stack.length > 0) {
    const curr = stack.pop();
    if (prev !== null) {                       // link in visiting order
      prev.next = curr;
      curr.prev = prev;
    }
    if (curr.next !== null) stack.push(curr.next);   // comes after the whole child level
    if (curr.child !== null) {
      stack.push(curr.child);                  // ...so the child level goes on top
      curr.child = null;
    }
    prev = curr;
  }
  return head;
}

